                modify rename node $e as xs:QName("hisco:employees") 
                return $e 
return namespace-uri-for-prefix("hisco", $newemps/myco:employee[1])

declare copy-namespaces preserve, no-inherit; 
declare namespace myco="http://www.example.com/myco"; 
declare namespace hisco="http://www.example.com/hisco"; 
let $myemps := <myco:employees salaried="false"> <myco:employee id='100'> <myco:name>Samuel</myco:name> </myco:employee> </myco:employees> 
let $newemps := copy $e := $myemps 
                modify rename node $e/@salaried as xs:QName("hisco:salaried") 
                return $e 
return namespace-uri-for-prefix("hisco", $newemps/myco:employee[1])

declare variable $input-context external; 
let $var := $input-context/works[1]/employee[13]/processing-instruction() 
return rename node $var as substring(normalize-space(" Xml" || current-date()), 1, 3)

copy $c := <e><a/></e>
modify rename node $c/a as 'x'
return count($c/x)

copy $c := <a/>
modify rename node $c as 'b'
return $c instance of element(a)

copy $c := <a a="v"/>
modify rename node $c/@a as QName('uri', 'p:a')
return namespace-uri-for-prefix('p', $c)

declare namespace p = 'u';
copy $c := <a/>
modify rename node $c as 'p:x'
return namespace-uri($c)

copy $c := <a/>
modify rename node $c as 'b'
return name($c)

copy $c := <a><b/></a>
modify rename node $c/b as 'c'
return ($c/c/.. is $c, count($c/*))

copy $c := document { <a/> }
modify rename node $c as 'new'
return $c

copy $c := <a><n>y</n></a>
modify rename node $c as $c/n
return name($c)

copy $c := <a/>
modify rename node $c as QName('http://www.w3.org/XML/1998/namespace', 'xml:b')
return name($c)
